// Test for llm/bash_parser (public API differential goldens).
// This test covers:
// - fix_bash_command vs. the authoritative Python reference kernel
//   (kimi-agent bash_core.fix_bash_command, temp dir pinned to C:/Temp):
//   full command bytes + all six metadata lists + changed() + warning()
// - process_unquoted vs. unquoted._process_unquoted
// - bash_compatibility_prelude vs. bash_core.bash_compatibility_prelude
// - BashFix value semantics (unchanged pass-through, equality)
//
// The golden table is generated by:
//   python scripts/gen_bash_fix_data.py --bash-parser-goldens \
//       --reference <kimi-agent>/bin/kimix_native/_shell_compat.py \
//       --reference-root <kimi-agent>

#include "ut/ut.hpp"

#include <llm/bash_parser/bash_parser.h>

#include <core/kimix_core.h>

#include <cstdio>

// GENERATED by scripts/gen_bash_fix_data.py --bash-parser-goldens.
#include "bash_parser_goldens.inc"

using namespace boost::ut;
using namespace kimix::llm::bash_parser;

namespace tests_unit_llm_test_bash_parser {

// The generated rows pin _windows_temp_dir to C:/Temp.
const FixOptions kGoldenOptions = [] {
    FixOptions options;
    options.temp_dir = "C:/Temp";
    return options;
}();

kimix::vector<kimix::string> split_sep(const char *joined) {
    kimix::vector<kimix::string> out;
    const kimix::string_view view(joined);
    if (view.empty()) {
        return out;
    }
    size_t start = 0;
    while (true) {
        const size_t found = view.find('\x1f', start);
        if (found == kimix::string_view::npos) {
            out.emplace_back(view.substr(start));
            break;
        }
        out.emplace_back(view.substr(start, found - start));
        start = found + 1;
    }
    return out;
}

bool lists_equal(const kimix::vector<kimix::string> &actual, const char *expected_joined) {
    const kimix::vector<kimix::string> expected = split_sep(expected_joined);
    if (actual.size() != expected.size()) {
        return false;
    }
    for (size_t i = 0; i < actual.size(); ++i) {
        if (actual[i] != expected[i]) {
            return false;
        }
    }
    return true;
}

} // namespace tests_unit_llm_test_bash_parser
using namespace tests_unit_llm_test_bash_parser;

int main(int argc, char *argv[]) {
    boost::ut::detail::cfg::parse_arg_with_fallback(argc, const_cast<const char **>(argv));

    "goldens_present"_test = [] {
        // A truncated golden file must not pass vacuously (plan Phase 6.6).
        expect(k_bash_parser_golden_count >= 1200u) << "golden corpus truncated";
    };

    "fix_bash_command_goldens"_test = [] {
        size_t mismatches = 0;
        size_t first_reported = 0;
        for (size_t i = 0; i < k_bash_parser_golden_count; ++i) {
            const bash_parser_golden &golden = k_bash_parser_goldens[i];
            const BashFix result = fix_bash_command(kimix::string_view(golden.command), kGoldenOptions);
            bool ok = true;
            if (result.command() != golden.fixed) {
                ok = false;
            }
            if (ok && !lists_equal(result.replacements(), golden.replacements)) {
                ok = false;
            }
            if (ok && !lists_equal(result.path_changes(), golden.path_changes)) {
                ok = false;
            }
            if (ok && !lists_equal(result.shell_wrappers(), golden.shell_wrappers)) {
                ok = false;
            }
            if (ok && !lists_equal(result.nul_fixes(), golden.nul_fixes)) {
                ok = false;
            }
            if (ok && !lists_equal(result.unsupported(), golden.unsupported)) {
                ok = false;
            }
            if (ok && !lists_equal(result.cmd_conditional_fixes(), golden.cmd_conditional)) {
                ok = false;
            }
            if (ok && result.changed() != golden.changed) {
                ok = false;
            }
            if (ok && result.warning() != golden.warning) {
                ok = false;
            }
            if (!ok) {
                mismatches += 1;
                if (first_reported < 40) {
                    first_reported += 1;
                    std::printf("MISMATCH row %zu\n  command:  [%s]\n  expected: [%s]\n  actual:   [%s]\n",
                                i, golden.command, golden.fixed, result.command().c_str());
                    std::printf("  exp repl=[%s] act repl_n=%zu\n", golden.replacements, result.replacements().size());
                    std::printf("  exp paths=[%s]\n", golden.path_changes);
                    for (const kimix::string &p : result.path_changes()) {
                        std::printf("  act path=[%s]\n", p.c_str());
                    }
                    std::printf("  exp nul=[%s]\n", golden.nul_fixes);
                    for (const kimix::string &p : result.nul_fixes()) {
                        std::printf("  act nul=[%s]\n", p.c_str());
                    }
                    std::printf("  exp shells=[%s] exp unsup=[%s] exp cmd=[%s] exp changed=%d\n",
                                golden.shell_wrappers, golden.unsupported, golden.cmd_conditional, (int)golden.changed);
                    for (const kimix::string &p : result.shell_wrappers()) {
                        std::printf("  act shell=[%s]\n", p.c_str());
                    }
                    for (const kimix::string &p : result.unsupported()) {
                        std::printf("  act unsup=[%s]\n", p.c_str());
                    }
                    for (const kimix::string &p : result.cmd_conditional_fixes()) {
                        std::printf("  act cmd=[%s]\n", p.c_str());
                    }
                    std::printf("  act changed=%d\n", (int)result.changed());
                    if (result.warning() != golden.warning) {
                        std::printf("  exp warn=[%s]\n  act warn=[%s]\n", golden.warning, result.warning().c_str());
                    }
                }
            }
        }
        expect(eq(mismatches, size_t(0))) << mismatches << " golden rows mismatched";
    };

    "process_unquoted_goldens"_test = [] {
        size_t mismatches = 0;
        for (size_t i = 0; i < k_bash_parser_golden_count; ++i) {
            const bash_parser_golden &golden = k_bash_parser_goldens[i];
            const kimix::string actual = process_unquoted(kimix::string_view(golden.command));
            if (actual != golden.unquoted) {
                mismatches += 1;
                if (mismatches <= 20) {
                    std::printf("UNQUOTED MISMATCH row %zu\n  command:  [%s]\n  expected: [%s]\n  actual:   [%s]\n",
                                i, golden.command, golden.unquoted, actual.c_str());
                }
            }
        }
        expect(eq(mismatches, size_t(0))) << mismatches << " process_unquoted rows mismatched";
    };

    "unchanged_result_is_original_bytes"_test = [] {
        // Embedded NUL + non-ASCII bytes must survive a pass-through result.
        // Built byte-by-byte: a C string literal would truncate at the NUL.
        static const char kBytes[] = {'e', 'c', 'h', 'o', ' ', '\x01', '\x02', ' ', 'c', 'a', 'f', '\xc3', '\xa9', ' ', '\x00', 't', 'a', 'i', 'l'};
        const kimix::string weird(kBytes, sizeof(kBytes));
        expect(eq(weird.size(), size_t(19)));
        const BashFix result = fix_bash_command(weird, kGoldenOptions);
        expect(eq(result.command(), weird));
        expect(eq(result.command().size(), size_t(19)));
        expect(!result.changed());
        expect(result.warning().empty());
    };

    "bash_compatibility_prelude_matches_reference_shape"_test = [] {
        // The reference prelude is ALL fallback definitions (table order)
        // joined by "\n", then one conditional `export -f` line per name,
        // with NO trailing newline (unlike fallback_prefix).  Verified
        // against bash_core.bash_compatibility_prelude() on Windows:
        // 52846 bytes, starting with the gtimeout definition and ending with
        // `... then export -f htop; fi`.
        const kimix::string prelude = bash_compatibility_prelude();
#ifdef KIMIX_PLATFORM_WINDOWS
        expect(eq(prelude.size(), size_t(52846))) << "prelude drifted from the reference (regenerate goldens?)";
        expect(prelude.find("if ! command -v gtimeout >/dev/null 2>&1; then gtimeout() {") == 0u);
        expect(prelude.find("if declare -F htop >/dev/null; then export -f htop; fi") == prelude.size() - 54u);
        expect(prelude.back() != '\n');
        // Every export line is present exactly once.
        size_t pos = 0;
        size_t exports = 0;
        while ((pos = prelude.find("if declare -F ", pos)) != kimix::string::npos) {
            exports += 1;
            pos += 1;
        }
        expect(eq(exports, size_t(88))) << "one conditional export per fallback name";
#else
        expect(prelude.empty()) << "non-Windows hosts get the empty prelude (reference sys.platform gate)";
#endif
    };

    "bashfix_value_semantics"_test = [] {
        const BashFix a("cmd");
        const BashFix b("cmd");
        expect(a == b);
        const BashFix c("cmd", {"rev"}, {}, {}, {}, {}, {});
        expect(a != c);
        expect(c.changed());
        // unsupported alone does not make changed() true
        const BashFix d("cmd", {}, {}, {}, {}, {"journalctl"}, {});
        expect(!d.changed());
        expect(!d.warning().empty());
    };
}
